// Structured kits for servants 1–58. Values are already PvP-scaled (flat HP ÷10, flat damage ÷20,
// NP Gain buffs ×0.5, control capped at 1T, NP drain = 30%). NPs use NP5 for 3★ and below, NP1 otherwise.
// Death chances are stored at their FGO value; the engine multiplies them by the Scaling death multiplier.
// Effect helpers ---------------------------------------------------------------
const S  = (s, v, t, o = {}) => ({ k: 'buff', to: 'self', s, v, t, ...o });
const AL = (s, v, t, o = {}) => ({ k: 'buff', to: 'allies', s, v, t, ...o });
const OA = (s, v, t, o = {}) => ({ k: 'buff', to: 'ally', s, v, t, ...o });
const OT = (s, v, t, o = {}) => ({ k: 'buff', to: 'others', s, v, t, ...o });
const E  = (s, v, t, o = {}) => ({ k: 'buff', to: 'enemy', s, v, t, ...o });
const EA = (s, v, t, o = {}) => ({ k: 'buff', to: 'enemies', s, v, t, ...o });
const NP = (to, v) => ({ k: 'np', to, v });
const HEAL = (to, v, o = {}) => ({ k: 'heal', to, v, ...o });
const STARS = (v, o = {}) => ({ k: 'stars', v, ...o });
const CLEANSE = to => ({ k: 'cleanse', to });
const CTRL = (kind, to, t, o = {}) => ({ k: 'control', kind, to, t, ...o });
const DOT = (kind, to, v, t, o = {}) => ({ k: 'dot', kind, to, v, t, ...o });
const STRIP = (to, which = 'all') => ({ k: 'strip', to, which });
const DRAIN = (to, v, p) => ({ k: 'drain', to, v, p });
const DEATH = (to, p, o = {}) => ({ k: 'death', to, p, ...o });
const GUTS = (to, hp, t, o = {}) => ({ k: 'guts', to, hp, t, n: 1, ...o });
const SELFDMG = v => ({ k: 'selfDmg', v });
const KO = () => ({ k: 'koSelf' });
const sk = (n, cd, e) => ({ n, cd, e });

